# Initially generated by GitHub Copilot.
"""Generate the process pipeline graph from structured pipeline data."""

from collections import defaultdict

from tmpl_survey import survey_dot

from pipeline_graph import pipeline_graph_spec as spec

_DISPLAY_BY_ID = {node.node_id: node for node in spec.DISPLAY_NODES}
_RAW_BY_ID = {node.raw_id: node for node in spec.RAW_NODES}
_OUT_DOT_PATH = "MAM-process-documentation/pipeline.dot"
_OUT_SVG_PATH = "MAM-process-documentation/pipeline.svg"


def _validate_spec():
    for raw_node in spec.RAW_NODES:
        assert raw_node.display_id in _DISPLAY_BY_ID, raw_node.display_id
    for raw_edge in spec.RAW_EDGES:
        assert raw_edge.source_id in _RAW_BY_ID, raw_edge.source_id
        assert raw_edge.target_id in _RAW_BY_ID, raw_edge.target_id
        assert raw_edge.section in spec.SECTION_ORDER, raw_edge.section


def _quote_dot(value):
    escaped = value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")
    return f'"{escaped}"'


def _attrs_text(attrs):
    if not attrs:
        return ""
    parts = []
    for key, value in attrs:
        if value in {"solid", "dashed"}:
            parts.append(f"{key}={value}")
            continue
        parts.append(f"{key}={_quote_dot(value)}")
    return " [" + ", ".join(parts) + "]"


def _node_line(node, tooltip_map, width):
    attrs = [("label", node.label)]
    tooltip = tooltip_map.get(node.node_id)
    if tooltip is not None:
        attrs.append(("tooltip", tooltip))
    attrs.extend(node.attrs)
    return f"    {node.node_id:<{width}}{_attrs_text(tuple(attrs))};"


def _collapsed_edges():
    seen = set()
    collapsed = []
    for raw_edge in spec.RAW_EDGES:
        source_id = _RAW_BY_ID[raw_edge.source_id].display_id
        target_id = _RAW_BY_ID[raw_edge.target_id].display_id
        edge_key = (raw_edge.section, source_id, target_id, raw_edge.attrs)
        if edge_key in seen:
            continue
        seen.add(edge_key)
        collapsed.append(edge_key)
    return collapsed


def _tooltip_map():
    grouped_labels = defaultdict(list)
    for raw_node in spec.RAW_NODES:
        grouped_labels[raw_node.display_id].append(raw_node.label)
    tooltips = {}
    for display_id, labels in grouped_labels.items():
        if len(labels) > 1:
            tooltips[display_id] = "\n".join(labels)
    return tooltips


def render_dot_text():
    _validate_spec()
    tooltips = _tooltip_map()
    node_width = max(len(node.node_id) for node in spec.DISPLAY_NODES) + 1
    lines = [
        "digraph mam_pipeline {",
        "    // Generated by py/main_pipeline_graph.py from structured pipeline data.",
        "    // Do not edit this file by hand; edit py/pipeline_graph/pipeline_graph_spec.py instead.",
        "    rankdir=LR;",
        '    node [fontname="Helvetica", fontsize=10];',
        '    edge [fontname="Helvetica", fontsize=9];',
        "",
        "    // ── Data stores ──",
        "    node [shape=cylinder];",
    ]
    for node in spec.DISPLAY_NODES:
        if node.section == spec.DATA_STORES:
            lines.append(_node_line(node, tooltips, node_width))
    lines.extend(
        [
            "",
            "    // ── External prerequisites (not part of _STEPS) ──",
            "    node [shape=box, style=dashed, color=gray, fontcolor=gray];",
        ]
    )
    for node in spec.DISPLAY_NODES:
        if node.section == spec.PREREQUISITES:
            lines.append(_node_line(node, tooltips, node_width))
    lines.extend(
        [
            "",
            "    // ── Pipeline steps ──",
            '    node [shape=box, style="", color="", fontcolor=""];',
        ]
    )
    for node in spec.DISPLAY_NODES:
        if node.section == spec.PIPELINE_STEPS:
            lines.append(_node_line(node, tooltips, node_width))
    lines.extend(["", "    // ── Edges ──", ""])
    edge_width = max(len(node.node_id) for node in spec.DISPLAY_NODES) + 1
    by_section = defaultdict(list)
    for section, source_id, target_id, attrs in _collapsed_edges():
        by_section[section].append((source_id, target_id, attrs))
    for section in spec.SECTION_ORDER:
        lines.append(f"    // {section}")
        for source_id, target_id, attrs in by_section[section]:
            edge_text = f"    {source_id:<{edge_width}}-> {target_id}"
            lines.append(f"{edge_text}{_attrs_text(attrs)};")
        lines.append("")
    lines.append("}")
    return "\n".join(lines) + "\n"


def write_dot_file(dot_path=_OUT_DOT_PATH):
    with open(dot_path, "w", encoding="utf-8") as out_file:
        out_file.write(render_dot_text())


def render_svg(dot_path=_OUT_DOT_PATH, svg_path=_OUT_SVG_PATH):
    rendered = survey_dot.render_svg(dot_path, svg_path)
    if not rendered:
        raise FileNotFoundError("Graphviz dot executable was not found")


def write_pipeline_files(dot_path=_OUT_DOT_PATH, svg_path=_OUT_SVG_PATH):
    write_dot_file(dot_path)
    render_svg(dot_path, svg_path)
